	/// Begin a fresh trajectory while retaining parameters and connectivity.
	pub fn begin_analysis(&mut self, ctx: &GeneratedEvalContext<'_>) {
		if ctx.evaluation_failed() { return; }
		self.stamp_state.ddt_current.fill(0.0);
		self.stamp_state.ddt_previous.fill(0.0);
		self.stamp_state.ddt_older.fill(0.0);
		self.stamp_state.ddt_derivative_current.fill(0.0);
		self.stamp_state.ddt_derivative_previous.fill(0.0);
		self.stamp_state.ddt_initialized.fill(false);
		self.stamp_state.ddt_candidate_valid.fill(false);
		self.event_state_accepted.fill(0.0);
		self.event_state_candidate.fill(0.0);
		self.reset_analog_tasks();
		self.time = 0.0;
		self.timestep = 0.0;
		self.ddt_coefficients = GeneratedDdtCoefficients::inactive();
		self.canonical_reactive.fill(0.0);
	}

	#[doc(hidden)]
	pub fn capture_persistent_state(&self) -> GeneratedVerilogAPersistentState {
		let event_variables = self.event_state_accepted.to_vec();
		GeneratedVerilogAPersistentState {
			ddt_previous: self.stamp_state.ddt_previous.to_vec(),
			ddt_older: self.stamp_state.ddt_older.to_vec(),
			ddt_derivative_previous: self.stamp_state.ddt_derivative_previous.to_vec(),
			ddt_initialized: self.stamp_state.ddt_initialized.to_vec(),
			idt_previous: self.stamp_state.idt_previous.to_vec(),
			idt_older: self.stamp_state.idt_older.to_vec(),
			idt_input_previous: self.stamp_state.idt_input_previous.to_vec(),
			idt_initialized: self.stamp_state.idt_initialized.to_vec(),
			idtmod: Vec::new(),
			event_variables,
			limiter_anchor: Vec::new(),
			limiter_initialized: Vec::new(),
		}
	}

	#[doc(hidden)]
	pub fn validate_persistent_state_shape(&self, state: &GeneratedVerilogAPersistentState) -> Result<(), String> {
		if state.idtmod.len() != Self::IDTMOD_STATE_COUNT { return Err(format!("generated idtmod checkpoint shape mismatch: expected {}, found {}", Self::IDTMOD_STATE_COUNT, state.idtmod.len())); }
		if state.ddt_previous.len() != Self::DDT_STATE_COUNT || state.ddt_older.len() != Self::DDT_STATE_COUNT || state.ddt_derivative_previous.len() != Self::DDT_STATE_COUNT || state.ddt_initialized.len() != Self::DDT_STATE_COUNT {
			return Err(format!("generated ddt checkpoint shape mismatch: expected {}, found {} / {} / {} / {}", Self::DDT_STATE_COUNT, state.ddt_previous.len(), state.ddt_older.len(), state.ddt_derivative_previous.len(), state.ddt_initialized.len()));
		}
		if state.idt_previous.len() != Self::IDT_STATE_COUNT || state.idt_older.len() != Self::IDT_STATE_COUNT || state.idt_input_previous.len() != Self::IDT_STATE_COUNT || state.idt_initialized.len() != Self::IDT_STATE_COUNT {
			return Err(format!("generated idt checkpoint shape mismatch: expected {}, found {} / {} / {} / {}", Self::IDT_STATE_COUNT, state.idt_previous.len(), state.idt_older.len(), state.idt_input_previous.len(), state.idt_initialized.len()));
		}
		if state.event_variables.len() != 29 {
			return Err(format!("generated event-state checkpoint shape mismatch: expected 29, found {}", state.event_variables.len()));
		}
		if state.ddt_previous.iter().chain(&state.ddt_older).chain(&state.ddt_derivative_previous).chain(&state.idt_previous).chain(&state.idt_older).chain(&state.idt_input_previous).chain(&state.limiter_anchor).any(|value| !value.is_finite()) {
			return Err("generated Verilog-A checkpoint contains non-finite persistent state".to_string());
		}
		if state.event_variables.iter().any(|value| value.is_nan()) {
			return Err("generated Verilog-A checkpoint event state contains NaN".to_string());
		}
		Ok(())
	}

	#[doc(hidden)]
	pub fn restore_persistent_state(&mut self, state: &GeneratedVerilogAPersistentState) -> Result<(), String> {
		self.validate_persistent_state_shape(state)?;
		self.stamp_state.ddt_previous.copy_from_slice(&state.ddt_previous);
		self.stamp_state.ddt_current.copy_from_slice(&state.ddt_previous);
		self.stamp_state.ddt_older.copy_from_slice(&state.ddt_older);
		self.stamp_state.ddt_derivative_previous.copy_from_slice(&state.ddt_derivative_previous);
		self.stamp_state.ddt_derivative_current.copy_from_slice(&state.ddt_derivative_previous);
		self.stamp_state.ddt_initialized.copy_from_slice(&state.ddt_initialized);
		self.stamp_state.idt_previous.copy_from_slice(&state.idt_previous);
		self.stamp_state.idt_current.copy_from_slice(&state.idt_previous);
		self.stamp_state.idt_candidate_previous.copy_from_slice(&state.idt_previous);
		self.stamp_state.idt_older.copy_from_slice(&state.idt_older);
		self.stamp_state.idt_input_previous.copy_from_slice(&state.idt_input_previous);
		self.stamp_state.idt_input_current.copy_from_slice(&state.idt_input_previous);
		self.stamp_state.idt_initialized.copy_from_slice(&state.idt_initialized);
		self.event_state_accepted.copy_from_slice(&state.event_variables[..Self::EVENT_STATE_COUNT]);
		self.event_state_candidate.copy_from_slice(&state.event_variables[..Self::EVENT_STATE_COUNT]);
		self.stamp_state.ddt_candidate_valid.fill(false);
		self.stamp_state.idt_candidate_valid.fill(false);
		self.reset_analog_tasks();
		Ok(())
	}

